import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

print(f"Is 1013 prime? {is_prime(1013)}")

N = 2025
S_N = N * (N + 1) // 2
print(f"S_2025 = {S_N}")
print(f"S_2025 - 1 = {S_N - 1}")

# Check if S_2025 - 1 is a perfect square
sqrt_minus_1 = math.isqrt(S_N - 1)
if sqrt_minus_1 * sqrt_minus_1 == S_N - 1:
    print("S_2025 - 1 is a perfect square.")
else:
    print("S_2025 - 1 is NOT a perfect square.")

